#[test]
fn test_scenario3_numerical_omega() {
    let golden = read_golden();
    let s = &golden["scenario3_numerical"];

    let zs = json_to_mat(&s["Zs"]);
    let ns = json_to_mat(&s["Ns"]);
    let sigma_ld = json_to_mat(&s["sigma_LD"]);
    let _omega_start = json_to_mat(&s["omega_start"]);
    let omega_python = json_to_mat(&s["omega_numerical"]);

    // Use the Rust numerical omega estimator.
    let cfg = OmegaConfig {
        numerical: true,
        perfect_gencov: false,
        equal_h2: false,
        tol: 1e-6,
        no_overlap: false,
    };
    let omega_rust = estimate_omega(&zs, &ns, &sigma_ld, &cfg).unwrap();

    // Numerical optimisation may not match exactly between scipy and our
    // Nelder-Mead — use a looser tolerance.
    for i in 0..omega_rust.nrows() {
        for j in 0..omega_rust.ncols() {
            let rust = omega_rust[(i, j)];
            let python = omega_python[(i, j)];
            let rel_err = (rust - python).abs() / python.abs().max(1e-12);
            assert!(
                rel_err < 0.05,
                "Numerical Omega mismatch at [{i},{j}]: Rust={rust:.8}, Python={python:.8}, rel_err={rel_err:.4}"
            );
        }
    }
}

