#[test]
fn test_flatten_rebuild_roundtrip_python() {
    // Verify that our flatten/rebuild Cholesky parameterisation matches
    // Python's by checking that rebuild(flatten(omega)) ≈ omega for
    // a test matrix from the golden outputs.
    let golden = read_golden();
    let s = &golden["scenario2"];
    let omega = json_to_mat(&s["omega_gmm_adj"]);

    // Only test roundtrip if omega is positive definite (required for Cholesky).
    let flat = flatten_out_omega(&omega);
    let rebuilt = rebuild_omega(&flat);

    assert_mat_close(&rebuilt, &omega, "flatten/rebuild roundtrip");
}

#[test]
fn test_nelder_mead_matches_scipy() {
    // Test that our Nelder-Mead can minimise a simple function to the same
    // point as scipy.optimize.minimize.
    // f(x) = sum((x_i - c_i)^2) where c = [1, 2, 3]
    let f = |x: &[f64]| {
        x.iter()
            .enumerate()
            .map(|(i, &v)| (v - (i as f64 + 1.0)).powi(2))
            .sum::<f64>()
    };
    let x0 = vec![0.0, 0.0, 0.0];
    let result = nelder_mead_generic(f, &x0, 0.5, 1e-6, 1e-8, 5000);

    for i in 0..3 {
        assert!(
            (result[i] - (i as f64 + 1.0)).abs() < 1e-3,
            "Nelder-Mead x[{i}] = {}, expected {}",
            result[i],
            i + 1
        );
    }
}
